"""
    Get ratio of variability (sum of squared differences of consecutive
    values) of folded and unfolded models.
    """
def get_p2p_scatter_2praw(model: Any) -> object {
    return model['scatter_2praw'];
}

test_blocks:
test "t0" {
    assert (get_p2p_scatter_2praw({'scatter_2praw': -1e-06}) == -1e-06);;
}

test "t1" {
    assert (get_p2p_scatter_2praw({'scatter_2praw': 1.23456789}) == 1.23456789);;
}

test "t2" {
    assert (get_p2p_scatter_2praw({'scatter_2praw': 1.2}) == 1.2);;
}

test "t3" {
    assert (
        get_p2p_scatter_2praw({'scatter_2praw': 0.0002118821514579022})
        == 0.0002118821514579022
    );;
}

test "t4" {
    assert (get_p2p_scatter_2praw({'scatter_2praw': 1e-06}) == 1e-06);;
}

test "t5" {
    assert (
        get_p2p_scatter_2praw({'scatter_2praw': 1.234567891234568}) == 1.234567891234568
    );;
}

test "t6" {
    assert (get_p2p_scatter_2praw({'scatter_2praw': 1.23456}) == 1.23456);;
}

test "t7" {
    assert (get_p2p_scatter_2praw({'scatter_2praw': 0.0}) == 0.0);;
}

test "t8" {
    assert (
        get_p2p_scatter_2praw({'scatter_2praw': 0.023903220063589695})
        == 0.023903220063589695
    );;
}

test "t9" {
